// Builds everything the app needs in one reply, for ONE workspace (the backend sends ?dataset=w12).
const DS = String($('Dashboard asks for the overview').first().json.query?.dataset || '');
const WS = Object.fromEntries($('Get workspaces').all().map(i => i.json).filter(w => w.key).map(w => [w.key, w]));
const W = WS[DS] || {};
const DA_OLD = Number(W.da_old ?? 55);
const DA_NEW = Number(W.da_new ?? 58);
const DA_NEW_FROM = W.da_new_from || '2026-07';
const mine = r => !!DS && /^w\d+$/.test(DS) && r.dataset === DS;
const URGENT_DAYS = 7;

const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
const year = today.year;
const monthLabel = (m) => DateTime.fromFormat(m, 'yyyy-MM').toFormat('LLLL yyyy');
const dayIn = v => v ? DateTime.fromISO(typeof v === 'string' ? v : new Date(v).toISOString()).setZone(zone).toISODate() : null;
const parseTimeline = (g) => {
  let t = {};
  try { t = JSON.parse(g.timeline || '{}') || {}; } catch (e) { t = {}; }
  if (!t.drafted && g.created_at) t.drafted = g.created_at;
  if (g.status !== 'draft' && g.approved_at) { const k = g.status === 'rejected' ? 'rejected' : 'approved'; if (!t[k]) t[k] = g.approved_at; }
  return t;
};

const pensionerRows = $('Get all pensioners').all().map(i => i.json).filter(p => p.name && mine(p));
const paymentRows = $('Get all pension payments').all().map(i => i.json).filter(r => r.name && r.month && mine(r));
const letterRows = $('Get all letters').all().map(i => i.json).filter(g => g.name && mine(g)).sort((a, b) => a.id - b.id);

const deadline = DateTime.fromObject({ year, month: 11, day: 30 }, { zone });
const daysLeft = Math.round(deadline.diff(today, 'days').days);

const letters = letterRows.map(g => ({
  id: g.id, name: g.name, bank: g.bank, issue_type: g.issue_type, amount_short: g.amount_short,
  problem_summary: g.problem_summary, letter: g.letter, letter_source: g.letter_source,
  status: g.status, created_at: g.created_at, decided_at: g.approved_at, timeline: parseTimeline(g)
}));

const pensioners = pensionerRows.map(p => {
  const openDate = DateTime.fromObject({ year, month: p.age >= 80 ? 10 : 11, day: 1 }, { zone });
  const verifiedUntil = dayIn(p.lc_verified_until);
  const submitted = !!verifiedUntil && verifiedUntil > deadline.toISODate();
  let lcStatus;
  if (submitted) lcStatus = 'done';
  else if (today < openDate) lcStatus = 'not_open_yet';
  else if (daysLeft < 0) lcStatus = 'missed';
  else if (daysLeft <= URGENT_DAYS) lcStatus = 'urgent';
  else lcStatus = 'open';

  const months = paymentRows
    .filter(r => r.name === p.name)
    .sort((a, b) => (a.month < b.month ? -1 : 1))
    .map(r => {
      const da = r.month >= DA_NEW_FROM ? DA_NEW : DA_OLD;
      const expected = Math.round(r.basic_pension * (1 + da / 100) - (r.commuted_amount || 0));
      const received = Number(r.amount_received) || 0;
      const difference = expected - received;
      const status = received === 0 ? 'missing' : (difference > 0 ? 'short' : 'ok');
      return { month: r.month, month_label: monthLabel(r.month), da_percent: da, expected, received, difference: Math.max(difference, 0), status };
    });
  const problems = months.filter(m => m.status !== 'ok');
  const myLetters = letters.filter(g => g.name === p.name);
  const latest = myLetters.length ? myLetters[myLetters.length - 1] : null;

  return {
    id: p.id, name: p.name, age: p.age, bank: p.bank, ppo_last4: p.ppo_last4, language: p.language,
    family_email: p.family_email || '', bank_account_last4: p.bank_account_last4 || null,
    basic_pension: Number(p.basic_pension) || 0, commuted_amount: Number(p.commuted_amount) || 0,
    consent_given_at: p.consent_given_at || null, consent_by: p.consent_by || null,
    life_certificate: {
      status: lcStatus, submitted,
      submitted_on: submitted ? dayIn(p.lc_submitted_on) : null,
      verified_until: submitted ? verifiedUntil : null,
      pramaan_id: submitted ? (p.pramaan_id || null) : null,
      recorded_by: submitted ? (p.lc_recorded_by || null) : null,
      window_opens: openDate.toFormat('d LLLL yyyy'), days_left: daysLeft
    },
    payments: {
      status: months.length === 0 ? 'no_data' : (problems.length ? 'problem' : 'ok'),
      amount_short: problems.reduce((s, m) => s + m.difference, 0),
      problem_months: problems.length,
      months
    },
    letter: latest ? { id: latest.id, status: latest.status } : null
  };
});

const lcCount = (s) => pensioners.filter(p => p.life_certificate.status === s).length;
const lCount = (s) => letters.filter(g => g.status === s).length;
const totals = {
  pensioners: pensioners.length,
  lc_submitted: lcCount('done'),
  lc_pending: lcCount('open') + lcCount('urgent') + lcCount('missed'),
  lc_urgent: lcCount('urgent'),
  lc_missed: lcCount('missed'),
  payment_problem_pensioners: pensioners.filter(p => p.payments.status === 'problem').length,
  payments_known: pensioners.filter(p => p.payments.status !== 'no_data').length,
  amount_pending: pensioners.reduce((s, p) => s + p.payments.amount_short, 0),
  letters_draft: lCount('draft'),
  letters_approved: lCount('approved'),
  letters_sent: lCount('sent'),
  letters_resolved: lCount('resolved'),
  letters_rejected: lCount('rejected')
};

return [{ json: {
  generated_at: DateTime.now().setZone(zone).toISO(),
  dataset: DS,
  settings: { da_old: DA_OLD, da_new: DA_NEW, da_new_from: DA_NEW_FROM },
  deadline: deadline.toFormat('d LLLL yyyy'),
  deadline_iso: deadline.toISODate(),
  days_left: daysLeft,
  totals,
  pensioners,
  letters
} }];
